package com.financecoach.controller;
import com.financecoach.dto.*;import com.financecoach.security.UserPrincipal;import com.financecoach.service.GoalService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/goals") public class GoalController {private final GoalService service;public GoalController(GoalService service){this.service=service;}@GetMapping public ResponseEntity<List<GoalDto>> list(@AuthenticationPrincipal UserPrincipal p){return ResponseEntity.ok(service.list(p.getId()));}@PostMapping public ResponseEntity<GoalDto> create(@AuthenticationPrincipal UserPrincipal p,@Valid @RequestBody GoalRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(p.getId(),r));}@PutMapping("/{id}")public ResponseEntity<GoalDto> update(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long id,@Valid @RequestBody GoalRequest r){return ResponseEntity.ok(service.update(p.getId(),id,r));}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long id){service.delete(p.getId(),id);return ResponseEntity.noContent().build();}}
